            case ItemID.MITHRIL_PLATELEGS:      return ITEM_NAME_MITHRIL_PLATELEGS;
            case ItemID.MITHRIL_PLATESKIRT:     return ITEM_NAME_MITHRIL_PLATESKIRT;
